 await expect(page.getByLabel('分享权重',{exact:true})).toHaveCount(0);await expect(page.getByRole('heading',{name:'好感度与自己的小心思',exact:true})).toBeVisible();await page.getByRole('heading',{name:'想你的时候，主动聊一会儿',exact:true}).locator('xpath=ancestor::section[1]').screenshot({path:'docs/settings-relationship.png',style:'.sg-section-nav,.sg-footer{visibility:hidden!important}'});await reloadExpanded(page);await expect(page.getByLabel('只发表情也自然接话',{exact:true})).toBeChecked();await expect(page.getByLabel('主人消息回应概率（%）',{exact:true})).toHaveValue('100');expect(errors).toEqual([]);
